import {
  meetsLevel,
  type LogEntry,
  type LogcatService,
} from '../domain/logcat';

/** An explicit synthetic history, generated by index rather than retained in memory. */
export function createDemoLogcatService(
  fail = false,
  initialLines = 0,
  repeatEach = 1,
  longLines = false,
): LogcatService {
  let sequence = 0;
  const captures = new Map<
    number,
    { started: number; paused: number | null }
  >();
  const count = (token: number) => {
    const capture = captures.get(token);
    return (
      capture?.paused ??
      initialLines +
        Math.floor((Date.now() - (capture?.started ?? Date.now())) / 400)
    );
  };
  function entry(id: number): LogEntry {
    const source = Math.floor(id / repeatEach);
    const level = source % 5 === 0 ? 'E' : source % 3 === 0 ? 'D' : 'I';
    return {
      id,
      repeatCount: 1,
      level,
      text: `10-10 12:00:${String(id % 60).padStart(2, '0')}.000  1234  1234 ${level} DemoApp: ${level === 'E' ? 'Simulated network error' : 'Simulated activity update'} #${source + 1}${longLines && source % 2 === 0 ? ` payload=${'abcdef'.repeat(1000)}` : ''}`,
    };
  }
  const period = 15 * repeatEach;
  const cycle = Array.from({ length: period }, (_, id) => entry(id));
  function ids(minimum: Parameters<LogcatService['page']>[1], grouped = false) {
    return cycle
      .filter(
        (entry) =>
          meetsLevel(entry, minimum) &&
          (!grouped || entry.id % repeatEach === 0),
      )
      .map((entry) => entry.id);
  }
  function filteredCount(
    token: number,
    minimum: Parameters<LogcatService['page']>[1],
    grouped = false,
  ) {
    const length = count(token);
    const eligible = ids(minimum, grouped);
    return (
      Math.floor(length / period) * eligible.length +
      eligible.filter((id) => id < length % period).length
    );
  }
  function row(
    minimum: Parameters<LogcatService['page']>[1],
    position: number,
    grouped = false,
  ) {
    const eligible = ids(minimum, grouped);
    return entry(
      Math.floor(position / eligible.length) * period +
        eligible[position % eligible.length]!,
    );
  }
  return {
    async packages() {
      return ['com.example.demo', 'com.android.settings'];
    },
    async start() {
      if (fail) throw new Error('Simulated Logcat connection failure.');
      const token = ++sequence;
      captures.set(token, { started: Date.now(), paused: null });
      return token;
    },
    async read(token) {
      return {
        counts: (['V', 'D', 'I', 'W', 'E', 'F'] as const).map((level) =>
          filteredCount(token, level),
        ),
        groupedCounts: (['V', 'D', 'I', 'W', 'E', 'F'] as const).map((level) =>
          filteredCount(token, level, true),
        ),
        error: null,
      };
    },
    async page(token, minimum, start, grouped = false) {
      const total = filteredCount(token, minimum, grouped);
      start = Math.min(start, total);
      return {
        start,
        entries: Array.from(
          { length: Math.min(200, total - start) },
          (_, index) => {
            const entry = row(minimum, start + index, grouped);
            return {
              ...entry,
              repeatCount: grouped
                ? Math.min(repeatEach, count(token) - entry.id)
                : 1,
            };
          },
        ),
      };
    },
    async search(token, request) {
      const end = Math.min(
        request.end,
        filteredCount(token, request.minimum, request.grouped),
      );
      let cursor = request.backward ? end : request.start;
      for (let scanned = 0; scanned < 2000; scanned++) {
        if (request.backward ? cursor <= request.start : cursor >= end)
          return { position: null, next: null };
        const position = request.backward ? cursor - 1 : cursor;
        if (
          row(request.minimum, position, request.grouped)
            .text.toLowerCase()
            .includes(request.query.toLowerCase())
        )
          return { position, next: null };
        cursor = request.backward ? position : position + 1;
      }
      await new Promise((resolve) => setTimeout(resolve, 0));
      return { position: null, next: cursor };
    },
    async stop(token) {
      captures.delete(token);
    },
    async pause(token) {
      const capture = captures.get(token);
      if (capture) capture.paused = count(token);
    },
    async clear() {},
  };
}
